export type FsusBinaryOperationId = keyof typeof fsusBinaryRoutes
export type FsusBinaryRouteDescriptor = typeof fsusBinaryRouteDescriptors[FsusBinaryOperationId]
export type FsusBinaryRouteSecurity = typeof fsusBinaryRouteSecurity[FsusBinaryOperationId]

export function buildFsusBinaryRoute(
  operationId: FsusBinaryOperationId,
  params: Record<string, string | number | bigint> = {},
  query?: URLSearchParams | Record<string, string | number | boolean | null | undefined>
): string {
  const descriptor = fsusBinaryRouteDescriptors[operationId]
  if (!descriptor) throw new Error(`fsus_binary_route_descriptor_missing:${String(operationId)}`)
  let path = descriptor.path.replace(/\{([^}:]+)(?::[^}]+)?\}/g, (_token, key: string) => {
    const value = params[key]
    if (value === undefined || value === null) {
      throw new Error(`fsus_binary_route_param_missing:${String(operationId)}:${key}`)
    }
    return encodeURIComponent(String(value))
  })
  const queryString = stringifyFsusBinaryRouteQuery(query)
  return queryString ? `${path}?${queryString}` : path
}

function stringifyFsusBinaryRouteQuery(query?: URLSearchParams | Record<string, string | number | boolean | null | undefined>): string {
  if (!query) return ""
  if (query instanceof URLSearchParams) return query.toString()
  const search = new URLSearchParams()
  for (const [key, value] of Object.entries(query)) {
    if (value !== undefined && value !== null) search.set(key, String(value))
  }
  return search.toString()
}
